def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    total = sum(values)
    count = len(values)
    return {
        "value": total / count,
        "trace": {
            "total": total,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": None
            }
        }
    }
